def display_experiment_output(ex_num):
    ex = MANUAL_OUTPUTS.get(ex_num)
    if not ex:
        print(f"[!] Invalid experiment number: {ex_num}. Available: 1 to 10")
        return
    print("\n" + "=" * 70)
    print(f"  EX. NO. {ex_num}: {ex['title']}")
    print("=" * 70)
    print(ex["output"])
    print("=" * 70 + "\n")

def main():
    if len(sys.argv) > 1:
        arg = sys.argv[1].lower().strip()
        if arg in ["all", "-a", "--all"]:
            for i in range(1, 11):
                display_experiment_output(i)
        elif arg.isdigit() and 1 <= int(arg) <= 10:
            display_experiment_output(int(arg))
        else:
            print("Usage: python aics_manual_output_generator.py [1-10|all]")
            sys.exit(1)
    else:
        print("=" * 70)
        print("  CY3764 - AI IN CYBER SECURITY: LAB MANUAL OUTPUTS")
        print("=" * 70)
        for i in range(1, 11):
            print(f"  [{i:2d}] {MANUAL_OUTPUTS[i]['title']}")
        print("  [all] Display All 10 Experiment Outputs")
        print("-" * 70)
        choice = input("Enter choice (1-10 or 'all'): ").strip().lower()
        if choice in ["all", "a"]:
            for i in range(1, 11):
                display_experiment_output(i)
        elif choice.isdigit() and 1 <= int(choice) <= 10:
            display_experiment_output(int(choice))
        else:
            print("[!] Exiting. No valid selection made.")

if __name__ == "__main__":
    main()
